def reference(label,url):return dict(label=label,url=url)
def make(ident,title,iso,url,start='',end='',**kw):
    fields=dict(iso=[iso],region='Океания',checked=CHECKED,language=LANG,languages=[],language_mode='unconfirmed',cost=UNKNOWN,note=GATE,reward=AWARD)
    fields.update(kw)
    fields.setdefault('level',T('B — национальный маршрут, не мировой финал','B — ruta nacional, no final mundial')if fields.get('scope')=='national'else T('C — местный / региональный маршрут','C — ruta local / regional'))
    e=event(ident,title,'Австралия' if iso=='AUS' else 'Новая Зеландия',url,start,end,**fields)
    return e

